/**
 * Modeled loosely on Berkeleytime's real catalog/schedule shapes. See
 * apps/frontend/src/lib/schedule/conflict.ts and
 * apps/frontend/src/lib/api/catalog.ts in the main repo for the real thing.
 */

export interface Meeting {
  /** [Mon, Tue, Wed, Thu, Fri], in that order. */
  days: boolean[];
  /** "HH:MM", 24-hour clock. */
  startTime: string;
  /** "HH:MM", 24-hour clock. */
  endTime: string;
}

/** A section as it comes back from the catalog/search endpoint. */
export interface CatalogSection {
  id: string;
  courseNumber: string;
  sectionNumber: string;
  meetings: Meeting[];
}

/** A section the student has already added to their schedule. */
export interface ScheduleSection {
  id: string;
  meetings: Meeting[];
}

/** The student's current schedule -- data the catalog's own query/index has no idea exists. */
export interface StudentSchedule {
  sections: ScheduleSection[];
}
